/**
 * Renders resolved scheme colors as the two generated mobile theme files: a
 * NativeWind stylesheet (light tokens in `@theme`, dark overrides under
 * `prefers-color-scheme`) and a TypeScript color map for props that take a
 * color value instead of a class, such as react-native-svg fills.
 */

const HEADER =
  "Generated by apps/mobile/scripts/gen-theme.mjs from src/app/styles/theme.css. Do not edit; run `node apps/mobile/scripts/gen-theme.mjs`.";

const IDENTIFIER = /^[A-Za-z_$][\w$]*$/;

/**
 * @typedef {import("./theme-tokens.mjs").ColorMap} ColorMap
 * @typedef {import("./theme-tokens.mjs").SchemeColors} SchemeColors
 */

/** @param {ColorMap} colors @param {string} indent */
function cssDeclarations(colors, indent) {
  return Object.entries(colors)
    .map(([name, value]) => `${indent}--color-${name}: ${value};`)
    .join("\n");
}

/**
 * The dark values that differ from light. NativeWind inlines a variable
 * declared once, so only these stay live and switch with the appearance.
 * @param {SchemeColors} schemes
 * @returns {ColorMap}
 */
function darkOverrides({ light, dark }) {
  return Object.fromEntries(
    Object.entries(dark).filter(([name, value]) => light[name] !== value)
  );
}

/**
 * The NativeWind theme stylesheet.
 * @param {SchemeColors} schemes
 */
export function renderThemeCss(schemes) {
  return [
    `/* ${HEADER} */`,
    "@theme {",
    cssDeclarations(schemes.light, "  "),
    "}",
    "",
    "@media (prefers-color-scheme: dark) {",
    "  :root {",
    cssDeclarations(darkOverrides(schemes), "    "),
    "  }",
    "}",
    "",
  ].join("\n");
}

/** @param {ColorMap} colors */
function objectLiteral(colors) {
  const lines = Object.entries(colors).map(([name, value]) => {
    const key = IDENTIFIER.test(name) ? name : JSON.stringify(name);
    return `    ${key}: "${value}",`;
  });
  return ["{", ...lines, "  }"].join("\n");
}

/**
 * The TypeScript color map, keyed by appearance and then token name.
 * @param {SchemeColors} schemes
 */
export function renderColorModule(schemes) {
  return [
    `// ${HEADER}`,
    "",
    "/** Theme colors as hex, per appearance, keyed by token name without `--color-`. */",
    "export const themeColors = {",
    `  light: ${objectLiteral(schemes.light)},`,
    `  dark: ${objectLiteral(schemes.dark)},`,
    "} as const;",
    "",
  ].join("\n");
}
